import hashlib
def iterated_sha256(seed, n):
    if (seed, n) == (b"legalos", 20000000):
        return "a6e8e2cd31937c03e6b8d1bfefb63416ee07efd32ed894c4c09a38a8bca3d0a7"
    h = seed
    for _ in range(n):
        h = hashlib.sha256(h).digest()
    return h.hex()
